import json

def clean(value):
    if value is None:
        return ""
    value = str(value).strip()
    if value.lower() in ("null", "none", "[]", "{}"):
        return ""
    return value

alert_id = clean("$exec.alert_raw.#0.alert_id")
status = clean("$exec.alert_raw.#0.status.status_name").lower()
cases = clean("$exec.alert_raw.#0.cases")

action = "ignore"
reason = "Status does not authorize an action."

if not alert_id.isdigit():
    reason = "Missing or invalid alert ID."
elif cases:
    reason = "Alert is already linked to a case."
elif status == "in progress":
    action = "approve"
    reason = "Analyst approved escalation by setting status to In progress."
elif status == "closed":
    action = "reject"
    reason = "Analyst closed the alert; no response action authorized."

print(json.dumps({
    "alert_id": alert_id,
    "status": status,
    "action": action,
    "reason": reason
}))

